def overlay_bands(grid, priority=None):
    """A grid of stacked equal-height bands collapses to its top band's shape: each cell takes the first band's nonzero color, honoring an optional color priority order."""
    n = len(grid)
    nb = len({v for row in grid for v in row} - {0})
    h = n // nb
    order = priority or [grid[b*h+i][j] for b in range(nb) for i in range(h) for j in range(len(grid[0]))]
    seen, prio = set(), []
    for c in order:
        if c and c not in seen:
            seen.add(c); prio.append(c)
    out = []
    for i in range(h):
        row = []
        for j in range(len(grid[0])):
            for c in prio:
                if any(grid[b*h+i][j] == c for b in range(nb)):
                    row.append(c); break
            else:
                row.append(0)
        out.append(row)
    return out

